from math import gcd


class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        ans = [-1] * n
        path = []

        def dfs(node, parent):
            for a in reversed(path):
                if gcd(nums[a], nums[node]) == 1:
                    ans[node] = a
                    break
            path.append(node)
            for nxt in graph[node]:
                if nxt != parent:
                    dfs(nxt, node)
            path.pop()

        dfs(0, -1)
        return ans

