class Solution {
    private List<List<Integer>> g;
    private int[] nums, ans;
    private final List<Integer> path = new ArrayList<>();

    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        this.nums = nums;
        ans = new int[n];
        Arrays.fill(ans, -1);
        g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }
        dfs(0, -1);
        return ans;
    }

    private void dfs(int node, int par) {
        for (int i = path.size() - 1; i >= 0; i--)
            if (gcd(nums[path.get(i)], nums[node]) == 1) {
                ans[node] = path.get(i);
                break;
            }
        path.add(node);
        for (int nxt : g.get(node))
            if (nxt != par) dfs(nxt, node);
        path.remove(path.size() - 1);
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

