from math import gcd


class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        cop = [[gcd(a, b) == 1 for b in range(51)] for a in range(51)]
        latest = {}
        ans = [-1] * n
        stack = [(0, 0, -1, 0)]
        while stack:
            typ, node, info, depth = stack.pop()
            if typ:
                latest[nums[node]] = info
                continue
            v = nums[node]
            best_node, best_depth = -1, -1
            for val in range(1, 51):
                e = latest.get(val)
                if e is not None and cop[val][v] and e[1] > best_depth:
                    best_node, best_depth = e
            ans[node] = best_node
            stack.append((1, node, latest.get(v), 0))
            latest[v] = (node, depth)
            for nxt in graph[node]:
                if nxt != info:
                    stack.append((0, nxt, node, depth + 1))
        return ans

